import { NextRequest, NextResponse } from 'next/server'
import { createClient as createServerClient } from '@/lib/supabase/server'
import {
  serviceClient,
  getUserFromBearer,
  resolveAccessForUser,
  getUnlockedKeysForMonth,
  AccessResolutionError,
  type ResolvedAccess,
} from '@/lib/data-access'
import {
  isKnownCounty,
  resolveDataFile,
  readCountyDataset,
  type RawCountyDataset,
} from '@/lib/county-data'

// Read fresh on each request — the dataset is regenerated by the pipeline and
// the locked/unlocked masking is per-user, so this must never be cached at the
// edge.
export const dynamic = 'force-dynamic'

// Financial fields that get nulled for locked (not-yet-unlocked) properties.
// This is the actual paywall: the client literally never receives these numbers
// for properties beyond the user's allowance — there is nothing to "un-blur".
const FINANCIAL_FIELDS = [
  // ── Valuation / profit / ROI (the headline numbers) ──────────────────────
  'arv',
  'arv_source',
  'arv_confidence',
  'net_profit',
  'gross_profit',
  'roi_percent',
  'roi_pct',
  'top_deal',
  'deal_score',
  'score_penalty',
  'recommended_max_bid',
  'max_bid',
  'min_bid',
  // ── Bid / cost inputs that reconstruct the deal ──────────────────────────
  'all_in_cost',
  'selling_costs',
  'net_proceeds',
  'estimated_rehab_cost',
  'estimated_rehab',
  'rehab_cost',
  'closing_costs',
  'carrying_total',
  'quiet_title_cost',
  'recording_fees',
  'title_insurance',
  'transfer_tax',
  'inspection_cost',
  'land_value',
  'land_value_source',
  // ── Comp-derived signals that reveal ARV ─────────────────────────────────
  'avg_comp_price',
  'avg_price_sqft',
  'comp_count',
  'comps_used_for_arv',
  'comp_pool_quality',
  'comp_window_months',
  'appraised_value',
  'assessed_value',
  'county_appraised_value',
  // ── Risk / equity signals ────────────────────────────────────────────────
  'risk_score',
  'estimated_equity',
  'mortgage_balance',
  'equity_tier',
  // ── As-is (resale-without-rehab) variant numbers ─────────────────────────
  'asis_net_profit',
  'asis_roi_percent',
  'asis_all_in_cost',
  'asis_sale_price',
  // calculation/explanation strings reveal the underlying numbers too
  'arv_calculation',
  'rehab_calculation',
  'rehab_notes',
  'profit_calculation',
  'roi_calculation',
  'all_in_breakdown',
  'all_in_calculation',
  'ranked_comps',
] as const

// Owner PII never belongs in a client payload, locked OR unlocked. The dashboard
// renders none of these fields; they were only ever leaking because the raw
// pipeline JSON was web-served.
const PII_FIELDS = ['owner', 'defendant', 'owner_type', 'raw_text'] as const

// Internal sourcing/vendor fields (how we gather and process data) are trade
// secrets — never shipped to any client tier. The dashboard renders none of
// them (founder direction 2026-07-04: "they shouldn't know how we are
// processing and generating our data").
const INTERNAL_SOURCE_FIELDS = [
  'comp_source', 'data_source_specs', 'arv_source', 'source', 'city_source',
] as const
const INTERNAL_SOURCE_PREFIXES = ['propstream_'] as const

function unlockKey(p: Record<string, unknown>, countySlug: string): string {
  const county = (p.county as string) || countySlug || 'unknown'
  const auction = (p.auction_date as string) || 'no-date'
  const parcel = (p.tax_id as string) || (p.parcel_id as string) || ''
  return [county, auction, parcel].join(':')
}

// Drop owner PII and any `_`-prefixed internal field. The raw pipeline JSON can
// carry internal bookkeeping keys (and we add our own `_unlockKey` join key
// downstream); none of those belong in the client payload. The one internal
// flag the client legitimately needs — `_unlocked` — is re-attached explicitly
// after this strip, so it is intentionally excluded from the leak.
function stripPii(p: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(p)) {
    if (k.startsWith('_')) continue
    if ((PII_FIELDS as readonly string[]).includes(k)) continue
    if ((INTERNAL_SOURCE_FIELDS as readonly string[]).includes(k)) continue
    if (INTERNAL_SOURCE_PREFIXES.some(prefix => k.startsWith(prefix))) continue
    out[k] = v
  }
  return out
}

// Street-level identity that the dashboard "blurs" on locked rows. Masking it
// here means the real value never reaches the client DOM (the old CSS blur left
// the true address in the markup, trivially un-blurred). City/zip/type stay so
// the user still has context for deciding whether to spend an unlock.
const LOCKED_ADDRESS_FIELDS = ['full_address', 'address', 'assessor_address'] as const
const LOCKED_ADDRESS_PLACEHOLDER = 'Unlock to view address'

function lockProperty(p: Record<string, unknown>): Record<string, unknown> {
  const out = stripPii(p)
  for (const f of FINANCIAL_FIELDS) {
    if (f in out) out[f] = null
  }
  for (const f of LOCKED_ADDRESS_FIELDS) {
    if (out[f]) out[f] = LOCKED_ADDRESS_PLACEHOLDER
  }
  return out
}

// Unlimited access ⇒ every row unlocked AND no per-month unlock ledger lookup.
// Both of those call sites MUST agree, which is why this is one predicate: when
// they drifted apart, an entitlement could be unlocked while still burning a
// ledger query (or worse, the reverse).
//
// Admins and web 'expert' qualify by tier. ANY active iOS (RevenueCat)
// subscription also qualifies, and that clause is required for correctness, not
// generosity: the RevenueCat webhook labels every iOS product 'pro'
// (revenuecat-webhook/mapping.ts planForProduct), but the mobile app ships no
// per-property unlock flow — it never calls POST /api/unlocks, and its paywall
// promises full access outright. Without this, a paying iOS subscriber inherits
// web 'pro''s 25/month allowance with no way to spend it, so every property
// returns null financials and "Unlock to view address": a paid-but-empty app.
// Web/Stripe 'pro' is deliberately NOT included — it keeps its metered 25/month.
function hasUnlimitedAccess(access: ResolvedAccess): boolean {
  return (
    access.isAdmin ||
    access.plan === 'expert' ||
    (access.provider === 'revenuecat' && access.plan !== null)
  )
}

// Expert-tier gate for the raw comp-sales dataset. Separate from
// hasUnlimitedAccess by design — see the comparables comment in applyAccess.
function hasComparablesAccess(access: ResolvedAccess): boolean {
  return access.isAdmin || access.plan === 'expert'
}

function applyAccess(
  dataset: RawCountyDataset,
  access: ResolvedAccess,
  unlockedKeys: Set<string>,
  countySlug: string,
): RawCountyDataset {
  const allUnlocked = hasUnlimitedAccess(access)

  const properties = dataset.properties.map(raw => {
    const key = unlockKey(raw, countySlug)
    let unlocked: boolean

    if (allUnlocked) {
      unlocked = true
    } else if (access.plan === null) {
      // No active subscription → nothing unlocked.
      unlocked = false
    } else if (unlockedKeys.has(key)) {
      unlocked = true
    } else {
      // Not previously unlocked. We do NOT auto-spend allowance here; unlocking
      // happens explicitly via POST /api/unlocks. So an un-clicked property is
      // locked regardless of remaining allowance.
      unlocked = false
    }

    // `key` is computed for the unlockedKeys lookup above but is internal — it
    // must NOT ship to the client (it previously leaked as `_unlockKey`).
    void key
    const shaped = unlocked ? stripPii(raw) : lockProperty(raw)
    return { ...shaped, _unlocked: unlocked }
  })

  // The top-level `comparables` array contains the raw comp sales that ARV is
  // derived from. Exposing it to locked tiers reconstructs the financials we
  // just masked, so it is withheld unless the caller has full access — and
  // even then its vendor `source` tag is stripped (sourcing is internal).
  //
  // Deliberately NOT hasUnlimitedAccess(): comparables are the Expert tier's
  // core value (~2,900 comp sales with address, price, date and lat/long). An
  // iOS subscriber is unlocked for PROPERTY data, but planForProduct() labels
  // every iOS product 'pro', so reusing the unlock predicate here would ship the
  // $249 Expert dataset to the cheapest iOS tier with no way to price around it.
  // Tier gates this; entitlement gates the property masking above.
  const comparables = hasComparablesAccess(access)
    ? dataset.comparables.map(c => {
        const rest = { ...c }
        delete rest.source
        return rest
      })
    : []

  return {
    ...dataset,
    properties,
    comparables,
  }
}

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ county: string }> },
): Promise<NextResponse> {
  const { county } = await context.params

  if (!isKnownCounty(county)) {
    return NextResponse.json({ error: 'Unknown county' }, { status: 404 })
  }

  // ── AUTHENTICATION ────────────────────────────────────────────────────────
  // Prefer the Authorization: Bearer <jwt> header (mobile + token-based web
  // clients); fall back to the Supabase cookie session for the web app.
  const svc = serviceClient()
  let user = await getUserFromBearer(request.headers.get('authorization'), svc)

  if (!user) {
    const supabase = await createServerClient()
    const { data } = await supabase.auth.getUser()
    user = data.user
  }

  if (!user) {
    return NextResponse.json({ error: 'Authentication required' }, { status: 401 })
  }

  // ── AUTHORIZATION ─────────────────────────────────────────────────────────
  // A lookup FAILURE must not degrade into "no plan" — that would mask the whole
  // dataset for a paying customer and look identical to an expired subscription.
  let access: ResolvedAccess
  try {
    access = await resolveAccessForUser(user, svc)
  } catch (err) {
    if (err instanceof AccessResolutionError) {
      console.error(`[api/data] entitlement lookup failed (${err.code}):`, err.message)
      return NextResponse.json(
        { error: 'Could not verify your subscription. Please try again.' },
        { status: 503 },
      )
    }
    throw err
  }

  // ── RESOLVE + READ DATASET (server-side only) ─────────────────────────────
  const requestedFile = request.nextUrl.searchParams.get('file')
  const resolved = await resolveDataFile(county, requestedFile)
  if (!resolved) {
    return NextResponse.json({ error: 'No dataset available' }, { status: 404 })
  }

  let dataset: RawCountyDataset
  try {
    dataset = await readCountyDataset(county, resolved.fileName)
  } catch (err) {
    console.error(`[api/data] failed to read ${county}/${resolved.fileName}:`, err)
    return NextResponse.json({ error: 'Dataset unavailable' }, { status: 500 })
  }

  // ── MASK PER ENTITLEMENT ──────────────────────────────────────────────────
  // Skip the ledger entirely when nothing is metered: unlimited tiers have
  // nothing to look up, and a null plan has nothing unlocked either way.
  const unlockedKeys =
    hasUnlimitedAccess(access) || access.plan === null
      ? new Set<string>()
      : await getUnlockedKeysForMonth(user.id, svc)

  const masked = applyAccess(dataset, access, unlockedKeys, county)

  const unlockedCount = masked.properties.filter(p => p._unlocked).length

  return NextResponse.json(
    {
      ...masked,
      access: {
        plan: access.plan,
        isAdmin: access.isAdmin,
        unlockLimit: access.unlockLimit,
        unlockedThisMonth: unlockedKeys.size,
        unlockedInResponse: unlockedCount,
      },
    },
    {
      status: 200,
      headers: { 'Cache-Control': 'private, no-store' },
    },
  )
}
